(()=>{"use strict";(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,91442,e=>{var n=e.i(43476),t=e.i(71645);let o={ko:e=>`이 대화에서는 Vibe Memory${"Claude"===e?" Connector":""}를 적극 사용해줘. 답변 전에 관련 기억이 도움이 되면 핵심 키워드만 추출해 검색하고, 사용자 정정\xb7결정\xb7선호\xb7다음 작업처럼 나중에도 유용한 맥락은 답변 후 간결하게 저장해. 서버가 추론한다고 가정하지 말고 네가 엔티티와 관계를 판단해 구조화해. 매 메시지마다 기계적으로 호출하지 말고 실제 연속성에 도움이 될 때 사용해.`,en:e=>`Use Vibe Memory${"Claude"===e?" Connector":""} proactively in this conversation. Before answering, search with a few extracted keywords when prior context would help. After answering, save concise durable context such as user corrections, decisions, preferences, and next actions. Do not assume the server infers entities or relationships; structure them yourself. Do not call it mechanically on every message—use it when it improves continuity.`,zh:e=>`请在本次对话中主动使用 Vibe Memory${"Claude"===e?" Connector":""}。回答前，如历史上下文有帮助，请提取少量核心关键词进行搜索；回答后，将用户更正、决定、偏好和后续任务等持久信息简洁保存。不要假设服务器会推断实体或关系，请自行判断并结构化。不要每条消息都机械调用，只在确实有助于连续性时使用。`,ja:e=>`この会話ではVibe Memory${"Claude"===e?" Connector":""}を積極的に使ってください。過去の文脈が役立つ場合は、回答前に少数の重要キーワードで検索し、回答後にユーザー訂正・決定・好み・次の作業など長期的に有用な文脈を簡潔に保存してください。サーバーがエンティティや関係を推論するとは考えず、自分で判断して構造化してください。毎回機械的に呼ばず、連続性に役立つ場合に使ってください。`,es:e=>`Usa Vibe Memory${"Claude"===e?" Connector":""} de forma proactiva en esta conversaci\xf3n. Antes de responder, busca con pocas palabras clave cuando el contexto previo sea \xfatil. Despu\xe9s, guarda de forma concisa correcciones, decisiones, preferencias y pr\xf3ximos pasos duraderos. No supongas que el servidor infiere entidades o relaciones: estruct\xfaralas t\xfa. No lo llames en cada mensaje; \xfasalo cuando mejore la continuidad.`,vi:e=>`H\xe3y chủ động d\xf9ng Vibe Memory${"Claude"===e?" Connector":""} trong cuộc tr\xf2 chuyện n\xe0y. Trước khi trả lời, chỉ t\xecm bằng v\xe0i từ kh\xf3a cốt l\xf5i khi ngữ cảnh trước đ\xf3 hữu \xedch. Sau khi trả lời, lưu ngắn gọn c\xe1c chỉnh sửa, quyết định, sở th\xedch v\xe0 việc tiếp theo c\xf3 gi\xe1 trị l\xe2u d\xe0i. Kh\xf4ng giả định m\xe1y chủ tự suy luận thực thể hay quan hệ; h\xe3y tự cấu tr\xfac ch\xfang. Kh\xf4ng gọi m\xe1y m\xf3c ở mọi tin nhắn, chỉ d\xf9ng khi gi\xfap duy tr\xec ngữ cảnh.`,th:e=>`ใช้ Vibe Memory${"Claude"===e?" Connector":""} อย่างกระตือรือร้นในการสนทนานี้ ก่อนตอบให้ค้นด้วยคีย์เวิร์ดสำคัญไม่กี่คำเมื่อบริบทเดิมมีประโยชน์ หลังตอบให้บันทึกการแก้ไข การตัดสินใจ ความชอบ และงานถัดไปที่ควรใช้ต่ออย่างกระชับ อย่าคิดว่าเซิร์ฟเวอร์อนุมานเอนทิตีหรือความสัมพันธ์เอง ให้จัดโครงสร้างด้วยตัวเอง และไม่ต้องเรียกทุกข้อความ ใช้เมื่อช่วยให้บริบทต่อเนื่องจริง`};function c({name:e}){return(0,n.jsx)("svg",{className:"svg-icon","aria-hidden":"true",children:(0,n.jsx)("use",{href:`/assets/icons.svg#${e}`})})}e.s(["ChatGuideActions",0,function({product:e,connectUrl:i}){let[a,r]=(0,t.useState)(null);async function s(){let n=window.vmCurrentLocale?.()||"ko";await navigator.clipboard.writeText(o[n](e)),r("prompt"),window.setTimeout(()=>r(null),1800)}async function u(){await navigator.clipboard.writeText("https://vibememory.io/mcp"),r("mcp"),window.setTimeout(()=>r(null),1800)}return(0,n.jsxs)("div",{className:"chat-guide-actions",children:[(0,n.jsxs)("a",{className:"button primary",href:i,target:"_blank",rel:"noopener",children:[(0,n.jsx)(c,{name:"external-link"})," 연결 화면 열기"]}),(0,n.jsxs)("button",{className:"button button-outline",type:"button",onClick:s,children:[(0,n.jsx)(c,{name:"prompt"===a?"check":"copy"}),"prompt"===a?"시작 프롬프트를 복사했습니다":"시작 프롬프트 복사"]}),(0,n.jsxs)("button",{className:"chat-copy-mcp",type:"button",onClick:u,children:[(0,n.jsx)("code",{children:"https://vibememory.io/mcp"}),(0,n.jsxs)("span",{children:[(0,n.jsx)(c,{name:"mcp"===a?"check":"copy"}),"mcp"===a?"복사됨":"MCP 주소 복사"]})]})]})}])},58055,e=>{var n=e.i(71645);e.s(["PublicHeaderControls",0,function(){return(0,n.useEffect)(()=>{window.vmMountLanguageSwitcher?.(),window.vmTheme?.mount?.()},[]),null}])}])})();